<script>const search=document.getElementById('field-search'),topic=document.getElementById('field-topic');function filterFields(){document.querySelectorAll('#field-rows tr').forEach(row=>{row.hidden=!(row.textContent.toLowerCase().includes(search.value.toLowerCase())&&(!topic.value||row.dataset.topic===topic.value));});}search.addEventListener('input',filterFields);topic.addEventListener('change',filterFields);const requestedField={{ \Illuminate\Support\Js::from(request('field')) }};if(requestedField){const row=[...document.querySelectorAll('[data-source-field]')].find(row=>row.dataset.sourceField===requestedField);if(row){const editor=row.querySelector('details');if(editor)editor.open=true;row.scrollIntoView({block:'center'});}}</script>
